import sympy

def prime_factors(n):
    result = {}
    while n % 2 == 0:
        if 2 in result:
            result[2] += 1
        else:
            result[2] = 1
        n = n // 2
    for i in range(3, int(n**0.5) + 1, 2):
        while n % i == 0:
            if i in result:
                result[i] += 1
            else:
                result[i] = 1
            n = n // i
    if n > 2:
        result[n] = 1
    return result

def total_exponents(n, prime_factorization):
    total = {}
    for prime, exponent in prime_factorization.items():
        total[prime] = 0
        while exponent % 2 == 0:
            total[prime] += 1
            exponent //= 2
        while exponent % 3 == 0:
            total[prime] += 1
            exponent //= 3
        while exponent % 5 == 0:
            total[prime] += 1
            exponent //= 5
        if exponent > 1:
