 Here is a Python code solution to find the number of ways Johnny can travel from $(0,0)$ to $(5,1)$ passing exactly through all twelve points in $S=\{(i, j) | 0 \leq i \leq 1,0 \leq j \leq 5, i, j \in \mathbb{Z}\}$ without ever crossing his own path.

```python
import networkx as nx

# Define the set S
S = set()

for i in range(6):
    for j in range(6):
        if i + j <= 5 or (i == 0 and j <= 1):
            S.add((i, j))

# Define the start and end points
start = (0, 0)
end = (5, 1)

# Create a graph
G = nx.Graph()

# Add nodes to the graph
G.add_nodes_from(S)

# Add edges to the graph
edges = []
for i in range(6):
    for j in range(6):
        if i - j >= 0 and (i, j) in S and (i-1, j-1) in S:
            edges.append(((i-1, j-1), (i, j)))

        if i + j <= 5 and (i, j) in S and (i+1, j+1) in S:
            edges.append(((i+1, j+1), (i, j)))

        if j - i >= 0 and (j, i) in S and (j-1, i+1) in S:
            edges.append(((j-1, i+1), (j, i)))

        if j <= i and (j, i) in S and (j, i+1) in S:
            edges.append(((j, i+1), (j, i)))

        if i >= 0 and (i, j) in S and (i, j-1) in S:
            edges.append(((i, j-1), (i, j)))

# Add edges to the graph
G.add_edges_from(edges)

# Count the number of ways to go from start to end without crossing
ways = 0
stack = [start]

while stack:
    current = stack.pop()
    if current == end:
        ways += 1
    for neighbor in G[current]:
        stack.append(neighbor)

print(f"Answer: {ways}")
```

