import numpy as np

def can_form_rectangle(points, grid_size):
    n = grid_size
    for i in range(n-1):
        for j in range(i+1, n):
            for p in points:
                for q in points:
                    if p != q:
                        if abs(p[0] - i) == abs(p[1] - j) and abs(q[0] - i) == abs(q[1] - j):
